#include <optional>
#include <vector>
#include <cstdint>
#include <stdexcept>
#include <cstring>

// Frame is assumed to be defined elsewhere as:
// struct Frame { std::vector<uint8_t> payload; size_t consumed; };

std::optional<Frame> decode_frame(const std::vector<uint8_t>& data, uint32_t max_payload) {
    // Need at least 4 bytes for the header
    if (data.size() < 4) {
        return std::nullopt;
    }

    // Read 4-byte little-endian payload length from the first 4 bytes
    uint32_t payload_len = static_cast<uint32_t>(data[0]) |
                           (static_cast<uint32_t>(data[1]) << 8) |
                           (static_cast<uint32_t>(data[2]) << 16) |
                           (static_cast<uint32_t>(data[3]) << 24);

    // Check if declared length exceeds max_payload — throw immediately, even if payload hasn't arrived
    if (payload_len > max_payload) {
        throw std::length_error("Payload length exceeds maximum allowed");
    }

    // Total frame size: 4-byte header + payload_len bytes of payload
    // Use uint64_t to avoid overflow in addition
    uint64_t total_size = static_cast<uint64_t>(4) + static_cast<uint64_t>(payload_len);

    // Check if we have enough data for the complete frame
    if (data.size() < total_size) {
        return std::nullopt;
    }

    // Extract payload bytes
    std::vector<uint8_t> payload(data.begin() + 4, data.begin() + 4 + payload_len);

    Frame frame;
    frame.payload = std::move(payload);
    frame.consumed = static_cast<size_t>(total_size);

    return frame;
}
