#include <cstdint>

bool transfer(uint64_t& source, uint64_t& destination, uint64_t amount) {
    // Reject zero amount
    if (amount == 0) {
        return false;
    }

    // Check if source and destination reference the same object
    if (&source == &destination) {
        return false;
    }

    // Check insufficient funds: source < amount
    if (source < amount) {
        return false;
    }

    // Check destination overflow: destination + amount > UINT64_MAX
    // Equivalent to: destination > UINT64_MAX - amount
    if (destination > UINT64_MAX - amount) {
        return false;
    }

    // Perform the transfer
    source -= amount;
    destination += amount;

    return true;
}
